#include <vector>
#include <unordered_map>
#include <algorithm>
#include <climits>

class Solution {
public:
    long long minSum(std::vector<int>& nums, int k) {
        long long prefix = 0;
        long long dp = 0;
        std::unordered_map<int, long long> best;
        best[0] = 0;

        for (int x : nums) {
            prefix += x;
            int rem = ((prefix % k) + k) % k;
            dp += x;
            if (best.count(rem)) {
                dp = std::min(dp, best[rem]);
            }
            if (!best.count(rem) || dp < best[rem]) {
                best[rem] = dp;
            }
        }
        return dp;
    }
};

import java.util.*;

class Solution {
    public long minSum(int[] nums, int k) {
        long prefix = 0;
        long dp = 0;
        Map<Integer, Long> best = new HashMap<>();
        best.put(0, 0L);

        for (int x : nums) {
            prefix += x;
            int rem = (int) (((prefix % k) + k) % k);
            dp += x;
            if (best.containsKey(rem)) {
                dp = Math.min(dp, best.get(rem));
            }
            best.put(rem, Math.min(best.getOrDefault(rem, Long.MAX_VALUE), dp));
        }
        return dp;
    }
}

